import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes0')
from h import *
X=[]
X.append(r(9049980,"Ensalada de col y quinoa","Esta ensalada de col y quinoa es rica en nutrientes y deliciosa, cubierta con un aderezo fresco y ácido que está listo en un momento.","8 porciones","1 porción",
["1 taza de quinoa","2 tazas de agua","½ cucharadita de sal marina","3 tazas de col morada rallada (aprox. la mitad de una col pequeña)","1 zanahoria grande rallada","1 pimiento morrón rojo picado en cubos","2 tazas de maíz congelado, descongelado","1 pepino grande cortado en cuartos a lo largo y en rebanadas","3 cebollitas de cambray (cebollines) en rebanadas finas","½ taza de cilantro o perejil picado (compactado)",("Ingredientes del aderezo","1.5 cucharadas de vinagre de arroz"),("Ingredientes del aderezo","¼ de taza de tamari o salsa de soya si no evita el gluten"),("Ingredientes del aderezo","1 limón verde recién exprimido"),("Ingredientes del aderezo","2 cucharadas de semillas de ajonjolí"),("Ingredientes del aderezo","1 cucharada de jarabe de arce (opcional)"),("Ingredientes del aderezo","½ cucharadita de ajo en polvo"),("Ingredientes del aderezo","¼ de cucharadita de pimienta de cayena")],
["En una olla pequeña, ponga la quinoa, el agua y la sal y hierva a fuego alto. Luego reduzca el fuego y cocine a fuego lento durante 10-12 minutos, hasta que se absorba el agua. Reserve y deje enfriar un poco.","En un tazón grande, combine todas las verduras picadas y la quinoa ya fría y mezcle bien.","Ponga todos los ingredientes del aderezo en un frasco o tazón pequeño y mezcle. Luego vierta el aderezo sobre la ensalada y mezcle para integrar.","Refrigere durante 1 hora antes de servir para que se enfríe. O disfrútela de inmediato si lo prefiere."],
["Use un rallador de caja o una herramienta para rallar la col y las zanahorias. Si usa un procesador de alimentos, trabaje por tandas y pulse para evitar procesar en exceso. Lo que busca es col y zanahoria ralladas, no en puré. Para más proteína, agregue a la mezcla una lata de garbanzos o frijoles negros escurridos y enjuagados. Si va a prepararla con anticipación, prepare y guarde la ensalada y el aderezo en recipientes separados en el refrigerador. Aderece la ensalada el mismo día en que planea comerla, para lograr la mejor textura. Para una versión sin azúcar, omita el jarabe de arce en el aderezo. Si puede consumir algo de azúcar, lo recomiendo para equilibrar la acidez. Sin embargo, de ambas maneras sabe muy bien. Para una versión sin soya, use aminos de coco en lugar del tamari. Las sobras se conservan en el refrigerador durante 2 días. Para conservarla por más tiempo, guarde el aderezo por separado y no aderece toda la ensalada. La ensalada sin aderezo se conservará en el refrigerador hasta por 1 semana."],[]))
X.append(r(9054548,"Sopa de quinoa con verduras en Instant Pot","Una sopa de quinoa en Instant Pot sustanciosa, saciante y llena de sabor, ¡con instrucciones para estufa también!","6 porciones","1 porción",
["1 cebolla amarilla picada en cubos","2 zanahorias grandes picadas en cubos","2 tallos de apio picados en cubos","2 calabacitas cortadas en cuartos a lo largo + en rebanadas gruesas","1.5 tazas de chícharos congelados","6 tazas de caldo de verduras bajo en sodio","2 tazas de salsa de tomate o puré de tomate, a su elección","1 taza de quinoa","5 onzas de espinacas baby","½ cucharadita de orégano seco","½ cucharadita de ajo en polvo","½ cucharadita de chile en polvo","sal + pimienta al gusto"],
[("Instrucciones para Instant Pot","Ponga la Instant Pot en modo de saltear. Agregue 3-4 cucharadas de agua con la cebolla, las zanahorias y el apio, y saltee hasta que se ablanden, aprox. 5 minutos. (Agregue más agua si es necesario para evitar que se peguen)."),("Instrucciones para Instant Pot","Agregue todos los demás ingredientes, excepto las espinacas, y revuelva. Cierre la tapa asegurándose de que la válvula esté en la posición de sellado. Luego programe a alta presión durante 2 minutos. (Tardará aprox. 15 minutos en alcanzar la presión). Cuando termine, libere el vapor rápidamente, retire la tapa e incorpore las espinacas revolviendo hasta que se marchiten."),("Instrucciones para estufa","En una olla grande para sopa, ponga 3-4 cucharadas de agua con la cebolla, las zanahorias y el apio, y saltee a fuego medio hasta que se ablanden, aprox. 5 minutos. (Agregue más agua según sea necesario para evitar que se peguen)."),("Instrucciones para estufa","Luego agregue todos los demás ingredientes, excepto las espinacas, tape la olla y hierva a fuego bajo. Después cocine la sopa a fuego lento durante 12-15 minutos, hasta que la quinoa esté cocida y la sopa haya espesado. Apague el fuego e incorpore las espinacas revolviendo hasta que se marchiten.")],
["Pique la cebolla, las zanahorias y el apio en trozos pequeños, pero deje las calabacitas en trozos más grandes para que no se cocinen en exceso ni queden demasiado blandas.","Si usa el método de la Instant Pot, asegúrese de que la válvula de la tapa esté en la posición de sellado, o no alcanzará la presión. Cuando termine el temporizador, libere el vapor de inmediato para evitar que se cocine en exceso.","Si usa el método de la estufa, mantenga la olla o cacerola tapada durante la cocción para evitar que los líquidos se evaporen demasiado y que la sopa quede demasiado espesa.","A medida que la sopa se enfría, la quinoa absorberá más caldo. Agregue un poco más de caldo, según sea necesario, si la sopa queda más espesa de lo que desea.","Las sobras se conservan en el refrigerador durante 3-4 días o puede congelarlas en un recipiente hermético hasta por 3 meses. Asegúrese de enfriar la sopa antes de congelarla y deje algo de espacio para que se expanda."],[]))
X.append(r(9057993,"Wafles de betabel","Estos vibrantes wafles veganos de betabel son un giro delicioso y original de un clásico del desayuno.","10 wafles","1 porción",
["2 tazas de leche de soya","2 cucharaditas de vinagre de manzana","1/3 de taza de compota de manzana sin azúcar","2 cucharadas de tahini","240 gramos de harina integral (aprox. 2 tazas)","2 cucharadas de betabel en polvo","2 cucharaditas de polvo para hornear"],
["Combine la leche de soya y el vinagre de manzana en un tazón grande y déjelos reposar durante 5 minutos para que espesen y se cuajen, creando su suero de leche vegano.","Precaliente la wafflera a temperatura media/alta, o según las indicaciones del fabricante.","En un tazón mediano, bata todos los ingredientes secos: la harina, el betabel en polvo y el polvo para hornear.","Para este momento, la leche de soya ya debe estar cuajada; agregue la compota de manzana y el tahini al tazón y revuelva. Luego agregue los ingredientes secos al mismo tazón y revuelva hasta que se integren, sin mezclar en exceso.","Cocine los wafles durante 6-8 minutos, o según las indicaciones del fabricante. No levante la tapa demasiado pronto o los wafles podrían pegarse y romperse. Revise con cuidado y, si parece que se están pegando, cocine 1-2 minutos más y revise de nuevo."],[],[]))
X.append(r(9064307,"Pizza vegana de queso","Una pizza vegana de queso en la que TODO GIRA EN TORNO AL QUESO.","8 rebanadas","1 porción",
["1 masa para pizza de 12 pulgadas (1 bola que se estire a aprox. 12 pulgadas)","⅓ de taza de salsa de tomate","1 cucharadita de orégano seco","1 cucharadita de ajo en polvo","1 taza colmada de mozzarella vegana","6-8 hojas de albahaca fresca"],
["Precaliente el horno a 450℉/232℃ en modo de hornear con convección y prepare un molde para pizza de 12 pulgadas. (Si no tiene convección, use la misma temperatura con el horneado normal).","Estire la masa sobre una encimera o tabla para cortar enharinada y pásela con cuidado al molde.","Extienda de manera uniforme la salsa de tomate y espolvoree los condimentos encima. Luego distribuya generosamente la mozzarella para cubrir la salsa.","Hornee durante 10-12 minutos, o hasta alcanzar el punto de cocción deseado."],
["Enharine la encimera y el rodillo para evitar que se pegue al estirar la masa de pizza.","Si no tiene un horno de convección, use la misma temperatura de horneado y aumente el tiempo de cocción según sea necesario.","Las sobras se conservan en el refrigerador durante 2-3 días en un recipiente cerrado o puede congelarlas en un recipiente hermético hasta por 3 meses."],[]))
X.append(r(9064409,"Bolitas energéticas de limón fáciles","Las bolitas energéticas de limón son un bocadillo delicioso y nutritivo, perfecto para satisfacer los antojos de algo dulce con ingredientes saludables.","22 bolitas","1 porción",
["1 taza de anacardos (nueces de la India) crudos","½ taza de coco rallado sin azúcar, y más para rodar las bolitas","1 taza de dátiles sin hueso, compactados","1 cucharada de ralladura de limón (de aprox. 1 limón grande)","2 cucharadas de jugo de limón","2-4 cucharadas de agua"],
["Ponga todo en el procesador de alimentos, comenzando con 2 cucharadas de agua. Procese hasta que se deshaga y obtenga una mezcla pegajosa y bien integrada. Agregue más agua si es necesario.","Tome porciones de la masa con una cucharita para galletas pequeña y forme una bolita. Coloque cada bolita energética de limón en un plato, una bandeja para hornear o una hoja de papel pergamino. Repita con el resto de la masa. Obtendrá alrededor de 22 bolitas energéticas.","Opcional: Pase cada bolita por más coco rallado usando un plato hondo."],
["No procese en exceso la mezcla. Estas bolitas de limón saben mejor con un poco de textura.","¡Ralle la cáscara del limón antes de exprimirlo! Y use jugo de limón fresco para obtener los mejores resultados.","Guarde las bolitas en un recipiente hermético en el refrigerador hasta por 5 días, o congélelas hasta por 3 meses."],[]))
X.append(r(9066125,"Salsa gravy de miso","Una salsa gravy de miso salada, sabrosa e increíblemente deliciosa que estará en su mesa en 10 minutos o menos.","8 porciones","1 porción",
["2 cucharadas de pasta de miso blanco","¾ de cucharadita de ajo en polvo","¾ de cucharadita de cebolla en polvo","½ cucharadita de mostaza amarilla","¼ de taza de harina integral blanca de trigo o harina de arroz integral para una versión sin gluten","2 tazas de caldo de verduras *use un caldo salado y con buen sabor"],
["Bata todos los ingredientes en una olla pequeña y hierva.","Luego baje el fuego a medio para mantener un hervor suave y bata con frecuencia hasta que espese. Sirva caliente."],
["Asegúrese de batir los ingredientes a temperatura ambiente (antes de empezar a calentar la salsa) para que la harina no forme grumos. Para una salsa de miso más espesa, agregue 2 cucharadas más de harina. Para una versión sin gluten, use harina de arroz integral. Las sobras se conservan en el refrigerador en un recipiente cerrado hasta por 5 días, o puede congelarlas en un recipiente hermético hasta por 3 meses. Espesará al enfriarse, así que aflójela con un chorrito de caldo o agua, según sea necesario, y recaliente en la estufa."],[]))
X.append(r(9066355,"Crème brûlée vegana [¡sin azúcar refinada!]","¡Una crème brûlée vegana cremosa y sedosa, con una capa crujiente de azúcar!","3 porciones","1 porción",
[("Para la base de crema","12 onzas (340 gramos) de tofu extra firme, escurrido (use soya no transgénica si es posible)"),("Para la base de crema","¼ de taza de azúcar de coco sin refinar"),("Para la base de crema","¼ de taza de jarabe de arce"),("Para la base de crema","2 cucharaditas de extracto puro de vainilla"),("Para la base de crema","1 cucharada de jugo de limón"),("Para la cubierta","3-6 cucharaditas de azúcar de coco (1 cucharadita por cada ramequín)"),("Para decorar","frambuesas, moras azules, fresas, menta")],
["Ponga todos los ingredientes de la base de crema en el procesador de alimentos y licue hasta que estén completamente integrados y suaves, raspando las paredes según sea necesario.","Pase la mezcla a los ramequines. (Yo usé tres ramequines de 6 onzas, o puede usar seis ramequines de 3-4 onzas para obtener más porciones). Luego refrigere durante al menos una hora (o toda la noche).","Después, espolvoree una cucharadita de azúcar de coco encima de cada base. Luego use un soplete de cocina para quemar el azúcar hasta que esté oscura y crujiente. Espere 2-3 minutos para que la cubierta de azúcar se enfríe y luego decore como desee."],
["Los sopletes de gas propano son altamente inflamables y deben mantenerse alejados del calor, de las llamas abiertas y de la exposición prolongada a la luz solar. Úselos solo en áreas bien ventiladas y siga las instrucciones del fabricante del soplete.","Usar azúcar de coco sin refinar para la cubierta significa que quedará más oscura que la de la crème brûlée tradicional, que usa azúcar blanca.","Las sobras se conservan en el refrigerador durante 3-4 días, pero sabe mejor cuando el azúcar está recién “quemada”."],[]))
X.append(r(9067847,"Camote horneado en freidora de aire","¡Prepare camotes horneados en su freidora de aire en un santiamén! Son deliciosos y más rápidos que con el método del horno.","2 porciones","1 porción",
["2 camotes largos y delgados, bien lavados (aprox. 6-7 pulgadas de largo/2-3 pulgadas de ancho)","1 cucharadita de aceite de aguacate (opcional; elija el método de cocción apropiado a continuación)",("Aderezos opcionales","tomate picado en cubos"),("Aderezos opcionales","crema de anacardos (nueces de la India)"),("Aderezos opcionales","perejil, cilantro o cebollín frescos")],
["Restriegue bien los camotes hasta dejarlos limpios y luego píquelos por todos lados con un tenedor o un cuchillo. Esto evitará que revienten en algunas partes mientras se cocinan en la freidora de aire.",("Para cocinar con el aceite opcional","Use una brocha de silicón o las manos para extender el aceite sobre la superficie de los camotes y luego cocine en la freidora de aire a 400 grados F durante 20-30 minutos, hasta que estén suaves y un tenedor los atraviese con facilidad."),("Para una versión sin aceite","Cocine los camotes en la freidora de aire a 350 grados F durante 25-35 minutos, hasta que estén suaves y se atraviesen fácilmente con un tenedor. Usar una temperatura más baja sin aceite evita que la cáscara se queme antes de que el interior tenga oportunidad de cocinarse por completo.")],[],[]))
save(3,X)
